package dev.falix.studiomobile;
import java.util.*;
/** Produces a real, minimal Roblox XML data model, not a renamed text placeholder. */
final class PlaceTemplate {
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String item(String cls,String name,String properties,String children){return "<Item class=\""+cls+"\" referent=\"RBX"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.US)+"\"><Properties><string name=\"Name\">"+esc(name)+"</string>"+properties+"</Properties>"+children+"</Item>";}
 static String vec(String name,double x,double y,double z){return "<Vector3 name=\""+name+"\"><X>"+x+"</X><Y>"+y+"</Y><Z>"+z+"</Z></Vector3>";}
 static String frame(double y){return "<CoordinateFrame name=\"CFrame\"><X>0</X><Y>"+y+"</Y><Z>0</Z><R00>1</R00><R01>0</R01><R02>0</R02><R10>0</R10><R11>1</R11><R12>0</R12><R20>0</R20><R21>0</R21><R22>1</R22></CoordinateFrame>";}
 static String part(String cls,String name,double y,double x,double sy,double z,long color,String extras){return item(cls,name,"<bool name=\"Anchored\">true</bool><bool name=\"CanCollide\">true</bool><float name=\"Transparency\">0</float><Color3uint8 name=\"Color3uint8\">"+color+"</Color3uint8><token name=\"Material\">256</token><token name=\"TopSurface\">0</token><token name=\"BottomSurface\">0</token>"+vec("size",x,sy,z)+frame(y)+extras,"");}
 static String generate(String name,String template,double gravity,boolean streaming){String children="";if("baseplate".equals(template)){children+=part("Part","Baseplate",-4,512,8,512,4285493103L,"");children+=part("SpawnLocation","SpawnLocation",.5,6,1,6,4288856576L,"<bool name=\"Enabled\">true</bool><bool name=\"Neutral\">true</bool><float name=\"Duration\">0</float>");}return "<roblox xmlns:xmime=\"http://www.w3.org/2005/05/xmlmime\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" version=\"4\"><External>null</External><External>nil</External>"+item("Workspace","Workspace","<float name=\"Gravity\">"+gravity+"</float><bool name=\"StreamingEnabled\">"+streaming+"</bool>",children)+item("Lighting","Lighting","<float name=\"ClockTime\">14</float><float name=\"Brightness\">2</float>","")+item("ReplicatedStorage","ReplicatedStorage","","")+item("ServerScriptService","ServerScriptService","","")+item("ServerStorage","ServerStorage","","")+item("StarterGui","StarterGui","","")+item("StarterPack","StarterPack","","")+item("StarterPlayer","StarterPlayer","","")+"</roblox>\n";}
}
